function seedRoll(seed: number): number {
  let value = seed >>> 0;
  value = Math.imul(value ^ (value >>> 16), 0x21f0aaad);
  value = Math.imul(value ^ (value >>> 15), 0x735a2d97);
  return (value ^ (value >>> 15)) >>> 0;
}

/** variant는 small 또는 dog:small 형식. 길고양이는 owner 대사를 하지 않는다. */
export function rivalLine(
  species: RivalSpecies,
  moment: RivalMoment,
  opts: { variant?: string; tone?: RivalTone; seed: number; last?: string; name?: string; owner?: string },
): string {
  const variant = opts.variant?.startsWith(`${species}:`) ? opts.variant : `${species}:${opts.variant}`;
  if (moment === "owner" && (variant === "cat:stray" || (species !== "dog" && species !== "cat"))) return "";
  const name = opts.name?.trim();
  const owner = opts.owner?.trim();
  const prepare = (lines: readonly string[]) => lines
    .filter(line => (!line.includes("{name}") || name) && (!line.includes("{owner}") || owner))
    .map(line => line.replaceAll("{name}", name ?? "").replaceAll("{owner}", owner ?? ""))
    .filter(line => Array.from(line).length <= 28 && !/[\r\n]/.test(line));
  const pool = prepare([...RIVAL_LINES[species][moment], ...(RIVAL_VARIANT_LINES[variant]?.[moment] ?? [])]);
  const tonePool = prepare(opts.tone ? RIVAL_TONE_LINES[species][opts.tone]?.[moment] ?? [] : []);
  const fresh = pool.filter(line => line !== opts.last);
  const freshTone = tonePool.filter(line => line !== opts.last);
  // 성격 선택과 줄 선택의 시드를 분리해 특정 대사로 쏠리지 않게 한다.
  const preferTone = opts.tone && seedRoll(opts.seed ^ 0x9e3779b9) % 100 < 70;
  const preferred = preferTone ? freshTone : fresh;
  const fallback = preferTone ? fresh : freshTone;
  const choices = preferred.length ? preferred : fallback.length ? fallback : pool.length ? pool : tonePool;
  return choices[seedRoll(opts.seed) % choices.length] ?? "";
}

export function shouldSpeak(moment: RivalMoment, seed: number): boolean {
  if (moment === "enter" || moment === "win" || moment === "lose" || moment === "flee") return true;
  const chance = moment === "finisher" || moment === "momentum" ? 80
    : moment === "crit_deal" || moment === "crit_take" ? 70
    : ["taunt", "attack", "hit", "low", "charge", "rest", "item", "defend", "miss", "effective", "ineffective", "round"].includes(moment) ? 30 : 25;
  return seedRoll(seed) % 100 < chance;
}
